def preprocess_string(s):
    # Remove spaces and punctuation, and convert to lowercase
    return re.sub(r'\W+', '', s).lower()

def longest_palindromic_subsequence(s, i, j, dp):
    if i > j:
        return 0
    if dp[i][j] != -1:
        return dp[i][j]
    if i == j:
        dp[i][j] = 1
    elif s[i] == s[j]:
        dp[i][j] = 2 + longest_palindromic_subsequence(s, i + 1, j - 1, dp)
    else:
        dp[i][j] = max(
            longest_palindromic_subsequence(s, i + 1, j, dp),
            longest_palindromic_subsequence(s, i, j - 1, dp)
        )
    return dp[i][j]

def lps(s):
    s = preprocess_string(s)
    n = len(s)
    if n == 0:
        return 0  # Edge case: empty string

    dp = [[-1] * n for _ in range(n)]
    return longest_palindromic_subsequence(s, 0, n - 1, dp)

