def nth_term(n):
    """Generate the nth term of the sequence."""
    if n == 0:
        return 1
    elif n == 1:
        return 1
    else:
        a, b = 1, 1
        for _ in range(2, n + 1):
            a, b = b, 2 * b + a
        return b

def is_prime(x):
    """Check if a number is prime."""
    if x < 2:
        return False
    for i in range(2, int(x**0.5) + 1):
        if x % i == 0:
            return False
    return True

def newman_prime(n):
    """Find the nth prime in the sequence of NSW primes."""
    found = 0
    i = 0
    while found < n:
        term = nth_term(i)
        if is_prime(term):
            found += 1
            if found == n:
